// Computes days since this matter's own Clio open date and matches it against the four
// onboarding-sequence days (0, 1, 3, 7). No external tracking of what's already been sent -- the
// open date alone tells this workflow exactly which stage, if any, applies today. Same 'compute
// the age, match an exact day' approach as PAC-18's invoice ladder and PAC-61's pre-bill compile.
const matter = $json;
const STAGE_DAYS = { 0: 'day0', 1: 'day1', 3: 'day3', 7: 'day7' };

const today = new Date();
today.setHours(0, 0, 0, 0);
const openDate = new Date(matter.open_date + 'T12:00:00Z');
openDate.setHours(0, 0, 0, 0);
const msPerDay = 24 * 60 * 60 * 1000;
const daysSinceOpen = Math.floor((today - openDate) / msPerDay);

return {
  json: {
    matter_id: matter.id,
    matter_ref: matter.display_number || '',
    matter_description: matter.description || '',
    client_name: (matter.client && matter.client.name) || '',
    client_email: (matter.client && matter.client.primary_email_address) || '',
    attorney_id: (matter.responsible_attorney && matter.responsible_attorney.id) || null,
    days_since_open: daysSinceOpen,
    stage: STAGE_DAYS[daysSinceOpen] || '',
  },
};

// Bridges the native Split Out / Filter chain above back to this catalog's usual explicit-skip
// pattern (see PAC-18, PAC-61, PAC-63): zero surviving matters becomes one clearly labelled
// sentinel item instead of the run just quietly having nothing execute, so a 'nothing due today'
// run still shows a clean, readable entry in execution history.
const items = $input.all();

if (items.length === 0) {
  return [{ json: { is_actionable: false, stage: 'none', reason: 'No matter hit an onboarding-sequence day today' } }];
}

return items.map(i => ({ json: { ...i.json, is_actionable: true } }));

// One node handles all four onboarding-sequence stages -- same pattern as the Invoice Reminder
// Ladder's (PAC-18) single build node keyed by ladder step -- so there's one place to edit copy
// instead of four near-duplicate nodes. Every stage is purely operational: portal access, process
// expectations, a document checklist, and how billing works. None of it comments on the matter's
// substance or gives legal guidance (ABA Op. 512).
//
// Resolves the matter's responsible_attorney id against the firm's user directory (fetched once
// per run in 'Fetch Firm Users From Clio') to personalize the welcome message and route the
// 'reach us at' mention to the actual assigned attorney -- falling back to the generic firm
// contact if the attorney can't be resolved (unassigned matter, disabled user, fetch failure).
const item = $input.first().json;
const FIRM_NAME = $vars.FIRM_NAME;
const FIRM_EMAIL = $vars.FIRM_EMAIL;
const PORTAL_URL = $vars.FIRM_CLIENT_PORTAL_URL || '';
const BILLING_EMAIL = $vars.FIRM_BILLING_EMAIL || FIRM_EMAIL;
const RESPONSE_DAYS = $vars.FIRM_RESPONSE_TIME_DAYS || '1-2';
const PAYMENT_TERMS_DAYS = $vars.FIRM_PAYMENT_TERMS_DAYS || '30';
const CHECKLIST = ($vars.FIRM_ONBOARDING_CHECKLIST || 'A government-issued photo ID\nYour signed engagement letter, if not already returned\nAny prior correspondence related to this matter\nContact information for anyone else involved')
  .split('\n').map(s => s.trim()).filter(Boolean).map(s => `- ${s}`).join('\n');

if (!FIRM_NAME) throw new Error('FIRM_NAME n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FIRM_EMAIL) throw new Error('FIRM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');

const users = ($('Fetch Firm Users from Clio API').first().json.data) || [];
const attorney = item.attorney_id ? users.find(u => u.id === item.attorney_id) : null;
const attorneyName = (attorney && attorney.name) || '';
const contactEmail = (attorney && attorney.email) || FIRM_EMAIL;
const teamLine = attorneyName ? `Your attorney, ${attorneyName}, and the rest of our team` : `Our team`;

const matterLabel = item.matter_ref + (item.matter_description ? ' (' + item.matter_description + ')' : '');

const STAGES = {
  day0: {
    subject: `Welcome to ${FIRM_NAME} — here's what happens next`,
    body: `Hi ${item.client_name},\n\nWelcome, and thank you for choosing ${FIRM_NAME} for your matter (${matterLabel}). ${attorneyName ? `${attorneyName} will be your attorney on this matter.` : `A member of our team will be your attorney on this matter.`}\n\n${PORTAL_URL ? `You can track your matter and message us anytime through our client portal:\n${PORTAL_URL}\n\nIf you haven't received separate login instructions yet, just let us know and we'll get you set up.` : `We'll follow up shortly with instructions for accessing your client portal.`}\n\nOver the next week you'll hear from us with a quick overview of what to expect, a short document checklist, and an explanation of how billing works — no action needed from you yet.\n\nQuestions in the meantime? Reach us at ${contactEmail}.\n\n${FIRM_NAME}`,
  },
  day1: {
    subject: `What to expect while we work on your matter`,
    body: `Hi ${item.client_name},\n\nA quick note on how we'll work together on ${matterLabel}:\n\n- ${teamLine} will reach out whenever we need information or a decision from you — no need to check in for status updates.\n- Most emails get a response within ${RESPONSE_DAYS} business day(s).\n- Any documents we need from you will come with clear instructions on how to send them.\n- You can always reach us at ${contactEmail} with questions.\n\nWe'll follow up in a couple of days with a short checklist of documents that help us get started.\n\n${FIRM_NAME}`,
  },
  day3: {
    subject: `A few documents that will help us get started`,
    body: `Hi ${item.client_name},\n\nTo keep things moving on ${matterLabel}${attorneyName ? ` with ${attorneyName}` : ''}, it helps to have the following on hand:\n\n${CHECKLIST}\n\nYou don't need to send everything at once — whatever you have is a good start, and ${attorneyName ? attorneyName + ' will' : "we'll"} follow up on anything still missing.\n\n${PORTAL_URL ? `You can upload documents directly through the client portal: ${PORTAL_URL}` : `Reply to this email or contact ${attorneyName || 'us'} at ${contactEmail} to send these over.`}\n\n${FIRM_NAME}`,
  },
  day7: {
    subject: `How billing works for your matter`,
    body: `Hi ${item.client_name},\n\nNow that ${attorneyName ? `${attorneyName} and the team are` : `we're`} underway on ${matterLabel}, here's a quick note on billing so nothing catches you by surprise:\n\n- Invoices are sent by email${PORTAL_URL ? ' and available in the client portal' : ''}.\n- You'll see an itemized breakdown of the time and work performed.\n- Payment is due within ${PAYMENT_TERMS_DAYS} days of the invoice date.\n- Questions about a bill? Contact us at ${BILLING_EMAIL} any time — we're happy to walk through it.\n\nThanks again for trusting ${FIRM_NAME}${attorneyName ? ` and ${attorneyName}` : ''} with your matter.\n\n${FIRM_NAME}`,
  },
};

const content = STAGES[item.stage];

return [{ json: {
  ...item,
  channel: 'email',
  recipient: item.client_email,
  subject: content.subject,
  message: content.body,
  template_id: 'PAC-64-client-onboarding',
  matter_id: String(item.matter_id || ''),
} }];
